create extension if not exists pgcrypto;
create extension if not exists postgis;
create type public.staff_role as enum ('caregiver','care_coordinator','agency_admin');
create type public.visit_state as enum ('scheduled','in_progress','verified','flagged_unverified','reviewed_billable','reviewed_non_billable');
create table public.agencies (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table public.staff_profiles (id uuid primary key references auth.users(id) on delete cascade, agency_id uuid not null references public.agencies(id), full_name text not null, role public.staff_role not null, created_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(), agency_id uuid not null references public.agencies(id), full_name text not null, service_address text not null, service_location geography(point,4326) not null, created_at timestamptz not null default now());
create table public.family_links (user_id uuid not null references auth.users(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, primary key(user_id,client_id));
create table public.scheduled_visits (id uuid primary key default gen_random_uuid(), agency_id uuid not null references public.agencies(id), client_id uuid not null references public.clients(id), caregiver_id uuid not null references public.staff_profiles(id), scheduled_start timestamptz not null, scheduled_end timestamptz not null, service_minutes integer not null check(service_minutes>0), required_tasks jsonb not null default '[]', created_at timestamptz not null default now());
create table public.visit_records (id uuid primary key default gen_random_uuid(), scheduled_visit_id uuid not null unique references public.scheduled_visits(id), status public.visit_state not null default 'scheduled', check_in_at timestamptz, check_out_at timestamptz, check_in_location geography(point,4326), check_out_location geography(point,4326), evidence_source text check(evidence_source in ('device_gps','manual')), distance_meters integer, duration_minutes integer, billable boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.visit_reviews (id uuid primary key default gen_random_uuid(), visit_record_id uuid not null references public.visit_records(id), reviewer_id uuid not null references public.staff_profiles(id), previous_status public.visit_state not null, resolved_status public.visit_state not null check(resolved_status in ('reviewed_billable','reviewed_non_billable')), reason text not null check(length(reason)>=12), created_at timestamptz not null default now());
create table public.care_notes (id uuid primary key default gen_random_uuid(), visit_record_id uuid not null unique references public.visit_records(id), draft jsonb not null, finalized_text text, status text not null default 'draft' check(status in ('draft','finalized')), finalized_by uuid references public.staff_profiles(id), finalized_at timestamptz, created_at timestamptz not null default now());
create table public.audit_events (id bigint generated always as identity primary key, agency_id uuid not null references public.agencies(id), actor_id uuid references auth.users(id), entity_type text not null, entity_id uuid not null, event_type text not null, payload jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.guard_visit_billing() returns trigger language plpgsql security definer set search_path=public as $$ begin
  if new.billable and new.status not in ('verified','reviewed_billable') then raise exception 'A visit cannot be billable without verified evidence or documented review'; end if;
  if new.status='verified' and (new.evidence_source<>'device_gps' or new.check_in_at is null or new.check_out_at is null or new.check_in_location is null or new.check_out_location is null) then raise exception 'Verified visits require complete device GPS evidence'; end if;
  if old.status='flagged_unverified' and new.status in ('reviewed_billable','reviewed_non_billable') and not exists(select 1 from public.visit_reviews where visit_record_id=new.id and resolved_status=new.status) then raise exception 'Documented review is required before resolving a flagged visit'; end if;
  new.updated_at=now(); return new; end $$;
create trigger visit_billing_guard before update on public.visit_records for each row execute function public.guard_visit_billing();
create or replace function public.prevent_audit_mutation() returns trigger language plpgsql as $$ begin raise exception 'Audit records are append-only'; end $$;
create trigger audit_immutable before update or delete on public.audit_events for each row execute function public.prevent_audit_mutation();
alter table public.agencies enable row level security; alter table public.staff_profiles enable row level security; alter table public.clients enable row level security; alter table public.family_links enable row level security; alter table public.scheduled_visits enable row level security; alter table public.visit_records enable row level security; alter table public.visit_reviews enable row level security; alter table public.care_notes enable row level security; alter table public.audit_events enable row level security;
create or replace function public.current_agency_id() returns uuid language sql stable security definer set search_path=public as $$ select agency_id from public.staff_profiles where id=auth.uid() $$;
create policy staff_own_agency on public.staff_profiles for select using(agency_id=public.current_agency_id());
create policy staff_clients on public.clients for all using(agency_id=public.current_agency_id()) with check(agency_id=public.current_agency_id());
create policy staff_visits on public.scheduled_visits for select using(agency_id=public.current_agency_id());
create policy assigned_or_coordinator_records on public.visit_records for select using(exists(select 1 from public.scheduled_visits sv join public.staff_profiles sp on sp.id=auth.uid() where sv.id=scheduled_visit_id and sv.agency_id=sp.agency_id and (sv.caregiver_id=auth.uid() or sp.role in ('care_coordinator','agency_admin'))));
create policy coordinator_reviews on public.visit_reviews for all using(exists(select 1 from public.staff_profiles sp where sp.id=auth.uid() and sp.role in ('care_coordinator','agency_admin'))) with check(exists(select 1 from public.staff_profiles sp where sp.id=auth.uid() and sp.role in ('care_coordinator','agency_admin')));
create policy staff_notes on public.care_notes for select using(exists(select 1 from public.visit_records vr join public.scheduled_visits sv on sv.id=vr.scheduled_visit_id join public.staff_profiles sp on sp.id=auth.uid() where vr.id=visit_record_id and sv.agency_id=sp.agency_id));
create policy family_finalized_notes on public.care_notes for select using(status='finalized' and exists(select 1 from public.visit_records vr join public.scheduled_visits sv on sv.id=vr.scheduled_visit_id join public.family_links fl on fl.client_id=sv.client_id where vr.id=visit_record_id and fl.user_id=auth.uid()));
create policy agency_audit_read on public.audit_events for select using(agency_id=public.current_agency_id());
revoke update,delete on public.audit_events from authenticated;
